function nextRouteSegment(segment: string): string | undefined {
  if (!segment || (segment.startsWith("(") && segment.endsWith(")"))) {
    return undefined;
  }
  const catchAll = segment.match(/^\[\.\.\.(.+)\]$/);
  if (catchAll?.[1]) {
    return `:${catchAll[1]}*`;
  }
  const dynamic = segment.match(/^\[(.+)\]$/);
  if (dynamic?.[1]) {
    return `:${dynamic[1]}`;
  }
  return segment;
}

